import{_ as e,o as s,c as l,a2 as n}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"AgoraIn Nexus 集控","description":"","frontmatter":{},"headers":[],"relativePath":"classisland-management.md","filePath":"classisland-management.md","lastUpdated":1792327070000}'),t={name:"classisland-management.md"};function i(o,a,r,d,c,h){return s(),l("div",null,[...a[0]||(a[0]=[n('<h1 id="agorain-nexus-集控" tabindex="-1">AgoraIn Nexus 集控 <a class="header-anchor" href="#agorain-nexus-集控" aria-label="Permalink to &quot;AgoraIn Nexus 集控&quot;">​</a></h1><p>AgoraIn Nexus 是定制版 ClassIsland 的正式名称。它通过 <strong>浏览器登录</strong> 连接 AgoraIn 平台，<strong>不再需要填写服务器地址、连接密码或区域代号</strong>。</p><h2 id="_1-登录" tabindex="-1">1. 登录 <a class="header-anchor" href="#_1-登录" aria-label="Permalink to &quot;1. 登录&quot;">​</a></h2><ol><li>打开 ClassIsland「设置 → AgoraIn 平台」；</li><li>点「浏览器登录（推荐）」，系统浏览器会打开官方登录页；</li><li>登录成功后回到 ClassIsland，账号会话自动写入本机；</li><li>选择本机所属班级与负责教师，点「登录并绑定」。</li></ol><p>服务器固定为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://agorain.615mc.cn</span></span></code></pre></div><p>生产版不提供服务器地址/密码输入框，不能连接到第三方或自建端点。</p><h2 id="_2-初始化向导" tabindex="-1">2. 初始化向导 <a class="header-anchor" href="#_2-初始化向导" aria-label="Permalink to &quot;2. 初始化向导&quot;">​</a></h2><p>首次启动 ClassIsland 时，「登录 AgoraIn Nexus」步骤同样使用浏览器登录：</p><ul><li>点「浏览器登录 AgoraIn」；</li><li>登录完成后自动读取可绑定班级；</li><li>选择班级与负责教师，勾选隐私政策，点「登录并继续」；</li><li>临时无法联网时可点「暂时跳过（离线使用）」。</li></ul><h2 id="_3-集控页面" tabindex="-1">3. 集控页面 <a class="header-anchor" href="#_3-集控页面" aria-label="Permalink to &quot;3. 集控页面&quot;">​</a></h2><p>「设置 → 集控」中的「了解更多」会打开本页。「加入管理」不再显示旧的 AgoraIn 官方端点输入框；需要连接平台请使用「设置 → AgoraIn 平台」。</p><h2 id="_4-浏览器拉不起来" tabindex="-1">4. 浏览器拉不起来 <a class="header-anchor" href="#_4-浏览器拉不起来" aria-label="Permalink to &quot;4. 浏览器拉不起来&quot;">​</a></h2><ul><li>确认系统默认浏览器可用；</li><li>手动复制 ClassIsland 提示的登录链接到浏览器；</li><li>登录回调使用本机回环端口 8765–8770，防火墙不要拦截本机回环；</li><li>仍失败时查看 ClassIsland 日志，并确认 <code>https://agorain.615mc.cn</code> 可访问。</li></ul><h2 id="_5-与旧密码方式的关系" tabindex="-1">5. 与旧密码方式的关系 <a class="header-anchor" href="#_5-与旧密码方式的关系" aria-label="Permalink to &quot;5. 与旧密码方式的关系&quot;">​</a></h2><p>服务端仍兼容旧的集控连接密码，用于特殊设备/迁移；<strong>生产版 ClassIsland 已隐藏密码输入</strong>，统一走浏览器登录。</p>',16)])])}const g=e(t,[["render",i]]);export{u as __pageData,g as default};
